  LearningPath(id: "dc01-dc02", number: "1.1", title: "Build the identity foundation", subtitle: "DC01 + DC02 / Active Directory & DNS", category: "Network build", description: "Configure Active Directory and DNS on Windows Server 2025, understand why two controllers matter, and keep a record of the build.", icon: "directory", published: true, studyTime: "5 guided chapters", topics: 5,
